const alternative = document.body.classList.contains('alternative');
const state = {page:'today',scenario:false,week:6,view:'ready',paused:false,approved:new Set(),rejected:new Set(),filter:'pending'};
const $ = (s) => document.querySelector(s);
const esc = (s) => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = (c) => new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR'}).format(c/100);
const btn = (text,action,cls='') => '<button class="btn '+cls+'" data-action="'+action+'">'+text+'</button>';
const badge = (text,kind='') => '<span class="status '+kind+'">'+text+'</span>';
const navItems = [['today','Today'],['forecast','Cash forecast'],['approvals','Approvals'],['documents','Documents'],['audit','Audit trail']];
const secondary = [['data','Company data'],['payees','Payees'],['bank','Demo bank'],['inbox','Test inbox']];
const actions = {
  move:{title:'Move the Inkworks payment',amount:1200000,subtitle:'Move €12,000 from 26 November to 11 December, within the invoice due date.',roles:['Owner'],tool:'reschedule_payment',args:{payment_id:'PAY-0001',new_date:'2026-12-11'},reason:'A non-critical payment can wait until its due date. This reduces the financing need to €10,000.',source:'AP-2052 / PAY-0001',cta:'Approve payment move'},
  finance:{title:'Prepare a financing application',amount:1000000,subtitle:'Supply-chain finance to bridge the remaining shortfall.',roles:['Owner','Accountant'],tool:'prepare_financing_application',args:{product_id:'supply_chain_finance',amount_cents:1000000,needed_by:'2026-11-23'},reason:'€10,000 for 38 days, with €120 total cost in the recorded demo. Assumes the Inkworks move is approved.',source:'Forecast week 6 / financing comparison',cta:'Approve preparation'}
};
function nav(items){return items.map(([id,label])=>'<button data-page="'+id+'" '+(state.page===id?'aria-current="page"':'')+'>'+label+(id==='approvals'?'<span class="nav-count">'+pendingCount()+'</span>':'')+'</button>').join('');}
function pendingCount(){return Object.keys(actions).filter(id=>!state.rejected.has(id)&&!(id==='move'&&state.approved.has(id))).length;}
function init(){
  $('#app').innerHTML='<a class="skip" href="#main">Skip to content</a><div class="demo-bar"><span>Design proposal '+(alternative?'B · React + TypeScript':'A · Streamlit')+' / Interactive HTML mockup / Sample data only</span><a href="index.html">Compare proposals</a></div><div class="shell"><aside class="sidebar"><div class="brand">runway<span>.</span></div><div><p class="nav-label">Workspace</p><nav aria-label="Main navigation">'+nav(navItems)+'</nav></div><div><p class="nav-label">Manage</p><nav aria-label="Company and demo">'+nav(secondary)+'</nav></div><div class="session"><p><strong>Lumen Packaging</strong></p><p class="muted">Owner / demo session</p><p id="agent-label" class="muted">Agent active within rules</p>'+btn('Pause agent','pause')+'<p class="small" style="margin-top:12px">EUR account currency</p></div></aside><div class="workspace"><header class="topbar"><div class="brand">runway<span>.</span></div><span class="company">Lumen Packaging</span><nav id="top-nav" aria-label="Workspace navigation">'+nav(navItems)+nav([['data','Manage company']])+'</nav><div class="identity"><small>Lumen Packaging</small><span>Owner / demo</span>'+(alternative?btn(state.paused?'Resume agent':'Pause agent','pause'):'')+'</div><button class="btn mobile-menu" data-action="menu" aria-expanded="false" aria-controls="top-nav">Menu</button></header><main id="main" class="content" tabindex="-1"></main></div></div><dialog id="review-dialog" class="review-dialog" aria-labelledby="review-title"></dialog><dialog id="info-dialog" aria-labelledby="info-title"></dialog><div id="toast" class="toast" role="status" aria-live="polite"></div>';
  render();
}
function heading(title,sub,button=''){return '<div class="page-heading"><div><h1>'+title+'</h1><p>'+sub+'</p></div>'+button+'</div>';}
function chart(){
  const vals=forecast.weeks.map(w=>w.closing_cents+(state.scenario&&w.index>=6&&w.index<=7?1200000:0));
  const x=i=>58+i*49.3,y=c=>214-(c+2000000)/10000000*175;
  const points=vals.map((v,i)=>x(i)+','+y(v)).join(' ');
  const grid=[8000000,4000000,0].map(v=>'<line class="'+(v===0?'zero':'guide')+'" x1="55" y1="'+y(v)+'" x2="657" y2="'+y(v)+'"/><text x="2" y="'+(y(v)+4)+'">'+(v===0?'€0':'€'+v/100000+'k')+'</text>').join('');
  return '<svg class="chart" viewBox="0 0 690 264" role="img" aria-label="13-week closing cash balance. Baseline shortfalls: week 6, minus 18,303 euros and 32 cents; week 10, minus 9,494 euros and 98 cents.'+(state.scenario?' Payment-move preview reduces the week 6 shortfall to 6,303 euros and 32 cents.':'')+'"><title>When does cash fall below zero?</title>'+grid+'<polyline class="line" points="'+points+'"/>'+vals.map((v,i)=>v<0?'<circle class="danger-point" cx="'+x(i)+'" cy="'+y(v)+'" r="5"/>':'').join('')+forecast.weeks.map((w,i)=>'<text class="week-label" data-essential="'+([1,6,10,13].includes(w.index))+'" text-anchor="middle" x="'+x(i)+'" y="245">'+(w.index===6||w.index===10?'W'+w.index:w.index)+'</text>').join('')+'</svg>';
}
function forecastPanel(){return '<section class="panel"><div class="panel-head"><h2>When does cash fall below zero?</h2><span class="small muted">19 Oct – 17 Jan</span></div><div class="panel-body">'+chart()+'<div class="chart-note"><span><i class="legend-line"></i>'+(state.scenario?'Payment-move preview':'Baseline closing balance')+'</span><span>Weekly closing balance / EUR</span></div></div><div class="panel-foot">Week 6: '+money(state.scenario?-630332:-1830332)+' &nbsp; / &nbsp; Week 10: −€9,494.98</div></section>';}
function actionRow(id){
  const a=actions[id], rejected=state.rejected.has(id), approved=state.approved.has(id);
  const status=rejected?badge('Rejected','bad'):approved?badge(id==='finance'?'Accountant needed':'Move approved',id==='finance'?'warn':'good'):badge(id==='move'?'Owner needed':'Two approvals','warn');
  return '<article class="action-row"><span class="action-step">'+(id==='move'?'1':'2')+'</span><div class="grow"><div class="row-label"><h3>'+a.title+'</h3></div><p>'+a.subtitle+'</p>'+status+'<div style="margin-top:8px">'+btn('Review '+(id==='move'?'payment move':'financing'),'review:'+id,'text')+'</div></div><div class="amount num">'+money(a.amount)+'</div></article>';
}
function today(){
 return heading('Your cash, this week','Monday 19 October 2026 / Simulated date',btn('Refresh brief','refresh'))+
 '<section class="risk-summary"><div>'+badge('Cash shortfall ahead','bad')+'<h2>'+(alternative?'Cash falls below zero in week 6.':'Cash falls below zero in weeks 6 and 10.')+'</h2><p>Payroll, VAT and supplier payments arrive before Brightfield’s receipts.</p></div><div class="low"><small>Lowest projected balance<br>23–29 November</small><strong class="num">−€18,303.32</strong></div></section>'+
 '<div class="balance-strip"><div><small>Available today</small><strong class="num">€40,000.00</strong></div><div><small>Forecast horizon</small><strong>13 weeks</strong></div><div><small>Waiting for review</small><strong>'+pendingCount()+' actions</strong></div></div>'+
 '<div class="grid"><div>'+forecastPanel()+'<section class="brief"><h2>The Monday brief</h2><p>Move Inkworks to its due date, then prepare €10,000 of financing for 38 days. The financing application needs both you and your accountant. The cash plan assumes the payment move goes ahead.</p><button class="btn text" data-page="forecast">Explore the forecast and sources</button></section><form class="chat-form" id="chat-form"><label for="chat-question" class="sr-only">Ask about this plan</label><input id="chat-question" placeholder="Ask about this plan…" required><button class="btn" type="submit">Ask Runway</button></form><div id="chat-response" aria-live="polite"></div></div><section class="panel"><div class="panel-head"><h2>The proposed plan</h2>'+badge('Needs your review','warn')+'</div><div class="action-row"><div class="grow"><h3>Chase two overdue invoices</h3><p>Reminders prepared for invoices AR-1091 and AR-1092.</p>'+badge('Automatic within limits','good')+'<div style="margin-top:8px"><button class="btn text" data-page="inbox">View test inbox</button></div></div><div class="amount num">€12,600.00</div></div>'+actionRow('move')+actionRow('finance')+'<div class="panel-foot">Proposed actions are checked against policy before they run.</div></section></div>'+
 '<section class="panel attention-row"><div><div class="row-label">'+badge('Payment blocked','bad')+'<h3>Cartonia invoice needs a human check</h3></div><p>A bank-detail-change instruction was detected. Linked payments stay blocked.</p></div><button class="btn" data-page="documents">Review document</button></section><div id="inline-review" class="inline-review"></div>';
}
function forecastPage(){
 const w=forecast.weeks[state.week-1];
 return heading('13-week cash forecast','Computed from ledger rows. Select a week to inspect its sources.')+
 '<div class="scenario-control"><label for="scenario">Compare a scenario</label><select id="scenario"><option value="baseline" '+(!state.scenario?'selected':'')+'>Baseline</option><option value="move" '+(state.scenario?'selected':'')+'>Move Inkworks to 11 December</option></select>'+badge('Preview only')+'</div>'+
 (state.scenario?'<div class="message warn">This preview moves €12,000 between weeks 6 and 8. It does not include financing or change any payment. The later week-10 gap remains.</div>':'')+
 forecastPanel()+'<div class="grid section-gap"><section class="panel"><div class="panel-head"><h2>Weekly balances</h2><span class="small muted">Select “Trace” for source rows</span></div><div class="table-wrap"><table><thead><tr><th>Week / starting</th><th>Closing balance</th><th>Evidence</th></tr></thead><tbody>'+forecast.weeks.map(v=>'<tr class="'+(state.week===v.index?'selected-row':'')+'"><td>W'+v.index+' <span class="muted">'+v.start.slice(5)+'</span></td><td class="num '+(v.closing_cents<0?'negative':'')+'">'+money(v.closing_cents+(state.scenario&&v.index>=6&&v.index<=7?1200000:0))+'</td><td><button class="table-button" data-week="'+v.index+'" aria-label="Trace week '+v.index+'">Trace</button></td></tr>').join('')+'</tbody></table></div></section><section class="panel" id="source-panel"><div class="panel-head"><h2>Week '+w.index+' / source breakdown</h2>'+badge('Recorded baseline')+'</div><div class="panel-body"><p class="small muted">'+w.start+' to '+w.end+'. Closing = opening + receipts + payments.</p><dl class="facts"><div><dt>Opening</dt><dd class="num">'+money(w.opening_cents)+'</dd></div><div><dt>Closing</dt><dd class="num">'+money(w.closing_cents)+'</dd></div><div><dt>Receipts</dt><dd class="num">'+money(w.receipts_cents)+'</dd></div><div><dt>Payments</dt><dd class="num">'+money(w.payments_cents)+'</dd></div></dl><h3>Contributing ledger rows</h3><div class="source-list">'+(w.lines.length?w.lines.map(l=>'<div class="source-row"><div>'+esc(l.label)+'<small>'+esc(l.source_refs.join(', '))+' / '+l.expected_date+'</small><small>'+esc(l.note)+'</small></div><strong class="num">'+money(l.amount_cents)+'</strong></div>').join(''):'<p class="muted">No receipts or payments this week. Closing equals opening.</p>')+'</div></div></section></div>';
}
function approvalPage(){
 let ids=Object.keys(actions).filter(id=>state.filter==='pending'?!state.rejected.has(id)&&!(id==='move'&&state.approved.has(id)):state.rejected.has(id)||(id==='move'&&state.approved.has(id)));
 return heading('Approval inbox','You are reviewing as Owner. Each approval is tied to a signed-in person.')+
 '<div class="tabs"><button class="btn" data-filter="pending" aria-pressed="'+(state.filter==='pending')+'">Pending ('+pendingCount()+')</button><button class="btn" data-filter="history" aria-pressed="'+(state.filter==='history')+'">History</button></div><div class="grid approval-layout"><section class="panel"><div class="panel-head"><h2>'+(state.filter==='pending'?'Actions waiting for a decision':'Decided actions')+'</h2></div>'+(ids.length?ids.map(actionRow).join(''):'<div class="empty-state"><h3>No '+(state.filter==='pending'?'pending':'decided')+' actions</h3><p>'+(state.filter==='pending'?'New proposals will appear here after you run a brief.':'Review an action to see its outcome here.')+'</p><button class="btn" data-page="today">Back to Today</button></div>')+'</section><section class="panel"><div class="panel-head"><h2>What your approval means</h2></div><div class="panel-body"><p class="small muted">You approve the exact amount, date and recipient shown in the request. Rules are checked again before execution.</p><div class="message">Financing above €5,000 requires Owner + Accountant in separate sessions.</div><p class="small muted">An application is prepared as a PDF. It is never submitted automatically.</p></div></section></div><div id="inline-review" class="inline-review"></div>';
}
function review(id){
 const a=actions[id], approved=state.approved.has(id),rejected=state.rejected.has(id);
 const disabled=approved||rejected||state.paused;
 const html='<section class="review"><div class="review-top"><div>'+badge(rejected?'Rejected':approved?(id==='finance'?'Waiting for Accountant':'Approved in mockup'):'Approval required',rejected?'bad':approved&&id==='move'?'good':'warn')+'<h2 id="review-title">'+a.title+'</h2><p>Proposal / '+a.source+'</p></div>'+btn('Close','close-review')+'</div><p>'+a.subtitle+'</p><dl class="facts"><div><dt>Amount / EUR</dt><dd class="num">'+money(a.amount)+'</dd></div><div><dt>'+(id==='move'?'Proposed date':'Needed by')+'</dt><dd>'+(id==='move'?'11 December 2026':'23 November 2026')+'</dd></div><div><dt>'+(id==='move'?'Current date':'Total financing cost')+'</dt><dd>'+(id==='move'?'26 November 2026':'€120.00')+'</dd></div><div><dt>'+(id==='move'?'Invoice due':'Duration')+'</dt><dd>'+(id==='move'?'11 December 2026':'38 days')+'</dd></div></dl><h3>Why this action</h3><p>'+a.reason+'</p>'+(id==='finance'?'<div class="message warn">Depends on the Inkworks payment move. Preparing an application does not mean financing is granted.</div>':'')+'<h3>Required approvals</h3>'+a.roles.map(r=>'<div class="approval-person"><span>'+r+'</span>'+badge(r==='Owner'&&approved?'Recorded':r==='Accountant'?'Separate sign-in required':'Waiting',r==='Owner'&&approved?'good':'warn')+'</div>').join('')+(state.paused?'<div class="message bad">Agent is paused. Read-only work remains available. Resume before approving.</div>':'')+(approved?'<div class="message good" role="status">'+(id==='finance'?'Your demo approval is recorded. The request is still pending until an Accountant approves from another session.':'Payment move approved in this mockup. No real payment was changed.')+'</div>':'')+'<details><summary>Exact request and policy context</summary><pre>'+esc(JSON.stringify(a.args,null,2))+'</pre><p>Policy is checked again at execution. Server credentials and approver identity must stay on the server.</p></details><div class="btn-row review-actions"><button class="btn primary" data-approve="'+id+'" '+(disabled?'disabled':'')+'>'+a.cta+'</button><button class="btn danger" data-reject="'+id+'" '+(disabled?'disabled':'')+'>Reject</button></div><p class="prototype-note">Local simulation only. This page cannot call the bank or create an application.</p></section>';
 if(alternative){$('#review-dialog').innerHTML=html;if(!$('#review-dialog').open)$('#review-dialog').showModal();}
 else{$('#inline-review').innerHTML='<div class="panel">'+html+'</div>';$('#inline-review').scrollIntoView({behavior:'instant',block:'start'});$('#inline-review button').focus();}
}
function documents(){
 return heading('Documents','Incoming invoices and emails are untrusted. Payment blocks remain visible.',btn('Preview upload','upload'))+
 '<section class="panel"><div class="panel-head"><h2>Needs attention</h2>'+badge('1 flagged document','bad')+'</div><article class="document-item"><div><h3>Cartonia / invoice CM-2026-0919</h3><p>Bank-detail-change instruction detected in document text.</p><p>Linked invoice: AP-2050 / Linked supplier: Cartonia</p></div><div class="btn-row">'+badge('Payments blocked','bad')+btn('Inspect flag','document')+'</div></article></section><section class="panel section-gap"><div class="panel-head"><h2>Document handling</h2></div><div class="panel-body"><p class="muted small">Review the source, confirm details outside the document, then let an authorised Owner or Accountant record the reason for clearing a flag. Clearing a flag does not verify a payee or execute a payment.</p></div></section>';
}
const auditEvents=[['Demo','Payment blocked','Cartonia document contains a bank-detail-change instruction.','Denied','bad'],['Demo','Financing proposed','Two independent approvals required above €5,000.','Pending','warn'],['Demo','Payment move proposed','Inkworks / €12,000 / 26 Nov to 11 Dec.','Pending','warn'],['Demo','Two reminders prepared','AR-1091 and AR-1092 / test inbox only.','Within limits','good']];
function auditPage(){return heading('Audit trail','The record behind each proposal, approval and refusal.',btn('Verify sample chain','verify'))+'<div id="verify-result" aria-live="polite"></div><section class="panel"><div class="panel-head"><h2>Decision timeline</h2>'+badge('Illustrative sequence')+'</div>'+[...Object.keys(actions).filter(id=>state.approved.has(id)||state.rejected.has(id)).map(id=>['Just now',state.rejected.has(id)?'Demo rejection':'Demo owner approval',actions[id].title+' / local prototype state.',state.rejected.has(id)?'Rejected':'Recorded',state.rejected.has(id)?'bad':'good']),...auditEvents].map(e=>'<article class="audit-row"><span class="muted">'+e[0]+'</span><div><h3>'+e[1]+'</h3><p>'+e[2]+'</p></div>'+badge(e[3],e[4])+'</article>').join('')+'</section>';}
function dataPage(){return heading('Company data','Review files before replacing the company dataset.')+'<div class="grid"><section class="panel"><div class="panel-head"><h2>Connect your books</h2>'+badge('Step 1 of 2')+'</div><div class="panel-body"><div class="upload"><label for="trial">Trial balance CSV / required</label><input id="trial" type="file" accept=".csv"></div><div class="upload"><label for="statement">Bank statement CSV / required</label><input id="statement" type="file" accept=".csv"></div><details><summary>Optional history files</summary><p class="small muted">Open receivables, open payables, paid invoices, and scheduled payments improve the forecast. Without payment history, the demo shortfall may not be reproduced.</p></details>'+btn('Preview import','import','primary')+'<div id="import-result" aria-live="polite"></div></div></section><section class="panel"><div class="panel-head"><h2>Current demo company</h2></div><div class="panel-body"><h3>Lumen Packaging</h3><p class="small muted">Fictional packaging supplier. Account currency: EUR.</p><dl class="facts"><div><dt>Invoices</dt><dd>156</dd></div><div><dt>Transactions</dt><dd>186</dd></div><div><dt>Available today</dt><dd>€40,000.00</dd></div><div><dt>Sample seed</dt><dd>42</dd></div></dl><div class="message warn">Import and reset replace the database and its audit log. The final confirmation must show what will be replaced.</div>'+secondary.filter(([id])=>id!=='data').map(([id,label])=>'<button class="btn text" data-page="'+id+'">'+label+'</button><br>').join('')+btn('Preview reset safeguards','reset')+'</div></section></div>';}
function payees(){return heading('Payees','Only an Owner can add or verify a payee. Agents cannot change bank details.')+'<section class="panel"><div class="panel-head"><h2>Recipient verification</h2></div><div class="document-item"><div><h3>Inkworks</h3><p>Linked to payment PAY-0001 and invoice AP-2052.</p></div>'+badge('Demo verified payee','good')+'</div><div class="document-item"><div><h3>Cartonia</h3><p>A document flag is blocking payments. Verification alone cannot clear it.</p></div>'+btn('Inspect linked flag','document')+'</div><div class="panel-foot">Full IBANs are omitted from this mockup. Production should mask bank details until an authorised review.</div></section>';}
function bank(){return heading('Demo bank','A clearly separated simulator. No real funds are connected.')+'<section class="panel"><div class="panel-head"><h2>Scheduled payment</h2>'+badge('Simulated')+'</div><div class="document-item"><div><h3>Inkworks / PAY-0001</h3><p>€12,000.00 / 26 November 2026 / invoice AP-2052</p></div>'+btn('Review proposed move','review:move')+'</div><div class="panel-body"><div class="message warn">Advancing the demo clock can execute scheduled mock payments. The confirmation must state the target date and affected payments.</div>'+btn('Preview clock advance','clock')+'</div></section><div id="inline-review" class="inline-review"></div>';}
function inbox(){return heading('Test inbox','A preview of outputs. No email is sent from this prototype.')+'<section class="panel"><div class="panel-head"><h2>Prepared payment reminders</h2>'+badge('Demo outputs')+'</div>'+[['AR-1091','€7,400.00'],['AR-1092','€5,200.00']].map(([id,amount])=>'<details style="padding:14px 22px"><summary>Payment reminder / '+id+' / '+amount+'</summary><p class="small muted">Recorded demo reminder for an overdue invoice. The implementation retains the existing email body and source invoice reference.</p></details>').join('')+'</section><section class="panel section-gap"><div class="panel-head"><h2>Financing application</h2></div><div class="panel-body"><p class="muted small">When both approvals are complete, the prepared PDF appears here for a human to review and sign. It is never submitted automatically.</p>'+btn('Review financing request','review:finance','text')+'</div></section><div id="inline-review" class="inline-review"></div>';}
const views={today,forecast:forecastPage,approvals:approvalPage,documents,audit:auditPage,data:dataPage,payees,bank,inbox};
function render(){
 let html;
 if(state.view==='ready')html=views[state.page]();
 else if(state.view==='loading')html=heading('Loading this view','Getting cash forecasts, proposals and source records.')+'<div class="panel empty-state" role="status"><h2>Loading company data…</h2><p>Approval controls will appear after the current request is loaded.</p>'+btn('Show loaded view','retry')+'</div>';
 else if(state.view==='error')html=heading('This view could not be loaded','No new action has been submitted.')+'<div class="panel empty-state" role="alert"><h2>Could not reach Runway</h2><p>Check your connection and retry. After a lost response, reload the action status before attempting it again.</p>'+btn('Retry loading','retry','primary')+'</div>';
 else html=heading('No company data yet','Connect the books to build a cash forecast.')+'<div class="panel empty-state"><h2>Start with the trial balance and bank statement</h2><p>Upload both required CSVs, or choose the sample company in the implementation.</p><button class="btn primary" data-page="data">Connect company data</button></div>';
 $('#main').innerHTML=html+'<p class="prototype-note">Sample company and recorded forecast / Fictional data / '+(alternative?'Proposed React interaction design; implemented here as standalone HTML.':'Streamlit-feasible layout study; native widgets may differ in the implementation.')+'</p><div class="view-state"><label for="view-state">Prototype state preview</label><select id="view-state"><option value="ready">Loaded</option><option value="loading">Loading</option><option value="error">Connection error</option><option value="empty">First run</option></select>'+btn('Reset local interactions','local-reset')+'</div>';
 $('#view-state').value=state.view;
 document.querySelectorAll('nav').forEach(n=>{const items=n.closest('.sidebar')?(n.getAttribute('aria-label')==='Main navigation'?navItems:secondary):[...navItems,['data','Manage company']];n.innerHTML=nav(items)+(n.closest(".topbar")?'<button class="btn mobile-pause" data-action="pause">Pause agent</button>':'');});
 document.querySelectorAll('[data-action="pause"]').forEach(b=>b.textContent=state.paused?'Resume agent':'Pause agent');
 if($('#agent-label'))$('#agent-label').textContent=state.paused?'Agent read-only':'Agent active within rules';
}
function notify(text){$('#toast').textContent=text;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').textContent='',6500);}
function info(title,html){$('#info-dialog').innerHTML='<div class="dialog-inner"><h2 id="info-title">'+title+'</h2>'+html+'<div class="btn-row">'+btn('Close preview','close-info')+'</div></div>';$('#info-dialog').showModal();}
document.addEventListener('click',e=>{
 const page=e.target.closest('[data-page]');if(page){state.page=page.dataset.page;state.view='ready';render();$('#top-nav').classList.remove('open');const menu=$('[data-action="menu"]');if(menu)menu.setAttribute('aria-expanded','false');$('#main').focus();window.scrollTo(0,0);return;}
 const week=e.target.closest('[data-week]');if(week){state.week=Number(week.dataset.week);render();$('#source-panel').scrollIntoView({behavior:'instant',block:'start'});return;}
 const filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;render();return;}
 const approval=e.target.closest('[data-approve]');if(approval){if(state.paused)return;const id=approval.dataset.approve;state.approved.add(id);render();review(id);notify(id==='finance'?'Owner approval recorded in mockup. Accountant approval is still required.':'Payment move approved in mockup. The baseline forecast is unchanged.');return;}
 const reject=e.target.closest('[data-reject]');if(reject){const id=reject.dataset.reject;info('Reject this proposal?','<p>The request will be marked rejected in this local preview. A real rejection is attributed to your signed-in role in the audit trail.</p>'+btn('Confirm rejection','confirm-reject:'+id,'danger'));return;}
 const el=e.target.closest('[data-action]');if(!el)return;
 const action=el.dataset.action;
 if(action.startsWith('review:')){review(action.split(':')[1]);return;}
 if(action.startsWith('confirm-reject:')){const id=action.split(':')[1];state.rejected.add(id);$('#info-dialog').close();render();review(id);notify('Proposal rejected in this mockup.');return;}
 if(action==='close-review'){if(alternative)$('#review-dialog').close();else{$('#inline-review').innerHTML='';$('#main').focus();}return;}
 if(action==='close-info'){$('#info-dialog').close();return;}
 if(action==='menu'){const open=$('#top-nav').classList.toggle('open');el.setAttribute('aria-expanded',String(open));return;}
 if(action==='pause'){state.paused=!state.paused;render();notify(state.paused?'Demo agent paused. Only read-only work remains available.':'Demo agent resumed within policy limits.');return;}
 if(action==='retry'){state.view='ready';render();return;}
 if(action==='local-reset'){state.approved.clear();state.rejected.clear();state.paused=false;state.scenario=false;state.filter='pending';state.view='ready';render();notify('Local interactions reset. No application data was touched.');return;}
 if(action==='refresh'){notify('Sample brief refreshed. The prototype does not call an AI provider.');return;}
 if(action==='verify'){$('#verify-result').innerHTML='<div class="message good">Recorded demo evidence reports 45 entries with an intact chain. This prototype does not verify the live database.</div>';return;}
 if(action==='document'){info('Cartonia / flagged invoice','<p>'+badge('Payments remain blocked','bad')+'</p><div class="flag-content"><h3>Reason for flag</h3><blockquote>Bank details changed / pay this IBAN</blockquote><p>This is a shortened example of the detected instruction, shown as plain text. Document content cannot issue commands.</p></div><h3>Before clearing</h3><ul class="info-list"><li>Verify the instruction with the supplier through a trusted channel.</li><li>Record an explanation as an Owner or Accountant.</li><li>Keep payee verification separate. Clearing does not execute any payment.</li></ul><p>The flag-clearing mutation is intentionally not simulated here.</p>');return;}
 if(action==='upload'){info('Preview document intake','<p>Choose an invoice PDF, email text or EML file in the implementation. Runway scans it before linking it to invoices and suppliers.</p><p>Show “Scanning document”, then either the stored document or a specific upload error. A flagged result keeps linked payments blocked.</p>');return;}
 if(action==='import'){const both=$('#trial').files.length&&$('#statement').files.length;$('#import-result').innerHTML='<div class="message '+(both?'warn':'bad')+'">'+(both?'Files selected locally. The implementation validates debits and credits, previews counts, then asks you to confirm replacement of company data and the audit log. This mockup does not read or import the files.':'Choose both required CSV files before previewing an import.')+'</div>';return;}
 if(action==='reset'){info('Reset sample company','<p>'+badge('Destructive in the real app','bad')+'</p><p>The implementation must name the company and explain that invoices, payments, documents and the audit log will be replaced before a separate confirmation.</p><p>This preview cannot reset any database.</p>');return;}
 if(action==='clock'){info('Advance the simulated date','<p>The implementation shows the new date and which scheduled mock payments may execute. Require a signed-in human and an explicit confirmation.</p><p>This prototype has no connection to the simulator.</p>');return;}
});
document.addEventListener('change',e=>{if(e.target.id==='scenario'){state.scenario=e.target.value==='move';render();}if(e.target.id==='view-state'){state.view=e.target.value;render();}});
document.addEventListener('submit',e=>{if(e.target.id!=='chat-form')return;e.preventDefault();$('#chat-response').innerHTML='<div class="message"><h3>Example reply / no model connected</h3><p>The first shortfall is −€18,303.32 in week 6. Moving Inkworks reduces that week’s gap by €12,000; the week-10 gap remains. Use the forecast to inspect the ledger rows.</p><button class="btn text" data-page="forecast">Trace the forecast</button></div>';});
init();
